VAS_CSS:
:host{display:block}
ha-card{overflow:hidden}
.wrap{position:relative;container-type:inline-size;--ease:cubic-bezier(.4,0,.2,1);
  --warm:var(--deep-orange-color,#ff6f22);--cold:var(--blue-color,#2196f3);--off:rgba(158,158,158,.42);
  --sky:var(--blue-color,#2196f3);--sky-a:.10;--lawn:var(--green-color,#4caf50);--lawn-a:.45;
  --ground:rgba(158,158,158,.14);--wall:rgba(158,158,158,.22);
  --dev:#f6f7f8;--devd:#4a4f55;--devl:rgba(0,0,0,.13);--shade:rgba(0,0,0,.045)}
.wrap.dark{--off:rgba(158,158,158,.22);--sky-a:.12;--lawn-a:.35;
  --ground:rgba(158,158,158,.10);--wall:rgba(158,158,158,.16);
  --dev:#2d3034;--devd:#4d5258;--devl:rgba(255,255,255,.10);--shade:rgba(0,0,0,.22)}
.lay{position:relative;container-type:inline-size}
.lay.narrow{display:none;max-width:460px;margin:0 auto}
@container (max-width:599.98px){.lay.wide{display:none}.lay.narrow{display:block}}
@container (max-width:699.98px){.lay.kk{display:none}.lay.kkn{display:block}}
.sc{position:relative}
.hd{padding:16px calc(16 * var(--g)) 0;font-family:var(--ha-font-family-body,Roboto,Noto,sans-serif)}
.hd .l1{display:flex;flex-wrap:wrap;align-items:baseline;column-gap:8px}
.hd .st{font-size:var(--ha-font-size-2xl,24px);line-height:32px;font-weight:var(--ha-font-weight-normal,400);color:var(--primary-text-color)}
.hd .dt,.hd .in{font-size:var(--ha-font-size-m,14px);line-height:20px;font-weight:var(--ha-font-weight-normal,400);color:var(--secondary-text-color)}
.hd .in.err{color:var(--error-color,#db4437)}.hd .in:empty{display:none}
.hd .lnk{cursor:pointer}.hd .in .lnk{white-space:nowrap}.hd .lnk:hover{color:var(--primary-text-color)}
svg{display:block;width:100%;height:auto}
.sky0{stop-color:var(--sky);stop-opacity:0}.sky1{stop-color:var(--sky);stop-opacity:var(--sky-a)}
.lawn{fill:var(--lawn);fill-opacity:var(--lawn-a)}.ground{fill:var(--ground)}.wall{fill:var(--wall)}
.dev{fill:var(--dev)}.devd{fill:var(--devd)}.devl{fill:none;stroke:var(--devl);stroke-width:1}
.shade{fill:var(--shade)}.side{fill:rgba(0,0,0,.18)}.plinth{opacity:.85}
.disp{fill:rgba(255,255,255,.14)}
.rib{fill:rgba(255,255,255,.08)}
.seam{stroke:rgba(0,0,0,.35);stroke-width:1.5}
.guard{fill:none;stroke:rgba(255,255,255,.16)}
.fan-disc{fill:#fff;fill-opacity:.07}
.fan path{fill:rgba(255,255,255,.6)}
.air path{fill:none;stroke:var(--secondary-text-color);stroke-width:1.5;stroke-linecap:round;opacity:.4}
.led{fill:rgba(255,255,255,.25)}.on-comp .led{fill:var(--green-color,#4caf50)}
.rad{fill:var(--dev);stroke:var(--secondary-text-color);stroke-opacity:.45;stroke-width:1}
.tap{cursor:pointer}
.pipe{fill:none;stroke-width:4;stroke-linecap:round;stroke-linejoin:round;stroke:var(--off);transition:stroke .3s var(--ease)}
.pipe.on.s{stroke:var(--warm)}.pipe.on.r{stroke:var(--cold)}
.fl{fill:none;stroke:#fff;stroke-width:1.5;stroke-linecap:round;stroke-dasharray:1 10;opacity:0;transition:opacity .3s var(--ease);pointer-events:none}
.fl.on{opacity:.9}
/* Refrigerant state in the refrigerant card: gas as sparse fast dots, liquid
   as a dense slow stream of dashes, the two-phase mix after an expansion
   valve as droplets. Each pattern length divides its animation offset. */
.fl.gas{stroke-dasharray:1 14}
.fl.liq{stroke-dasharray:14 4;stroke-width:2;stroke-linecap:butt}.fl.on.liq{opacity:.6}
.fl.mix{stroke-dasharray:4 7}
.valve{fill:var(--card-background-color);stroke:var(--divider-color)}
.ptr{stroke:var(--primary-text-color);stroke-width:2.5;stroke-linecap:round;transition:transform .3s var(--ease),opacity .3s var(--ease)}
.p2{opacity:0}.mixed .p2{opacity:1}
.hub{fill:var(--primary-text-color)}
.hit{fill:transparent}
.ptri{fill:none;stroke:var(--secondary-text-color);stroke-width:1.5;stroke-linejoin:round;transition:fill .3s var(--ease),stroke .3s var(--ease)}
.pump.on .ptri{fill:var(--warm);stroke:var(--warm)}
.coil{fill:none;stroke:var(--secondary-text-color);stroke-width:1.5;stroke-linejoin:round;stroke-linecap:round;transition:stroke .3s var(--ease)}
.heater.on .coil{stroke:var(--warm);stroke-width:2}
.nohit{pointer-events:none}
.wire{fill:none;stroke:var(--secondary-text-color);stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round;opacity:.6}
@keyframes vas-flow{to{stroke-dashoffset:-22}}
@keyframes vas-gas{to{stroke-dashoffset:-30}}
@keyframes vas-liq{to{stroke-dashoffset:-36}}
@keyframes vas-mix{to{stroke-dashoffset:-33}}
@keyframes vas-spin{to{transform:rotate(360deg)}}
@keyframes vas-drift{0%{transform:translateX(-6px);opacity:0}40%{opacity:.55}100%{transform:translateX(6px);opacity:0}}
@media (prefers-reduced-motion:no-preference){
  .fl.on{animation:vas-flow 1.1s linear infinite}
  .spin .fan{animation:vas-spin var(--fan-dur,1.4s) linear infinite}
  .fl.on.gas{animation:vas-gas .9s linear infinite}
  .fl.on.liq{animation:vas-liq 2.4s linear infinite}
  .fl.on.mix{animation:vas-mix 1.6s linear infinite}
  .fl.on.rev{animation-direction:reverse}
  .run .air path{animation:vas-drift 2.4s ease-in-out infinite}
  .run .air path:nth-child(2){animation-delay:.4s}
  .run .air path:nth-child(3){animation-delay:.8s}
}
.ov{position:absolute;inset:0;pointer-events:none;font-family:var(--ha-font-family-body,Roboto,Noto,sans-serif)}
.lb{position:absolute;transform:translate(-50%,-50%);white-space:nowrap;text-align:center;font-weight:500}
.lb.title{font-size:calc(14 * var(--u));color:var(--primary-text-color)}
.lb.cap{font-size:calc(13 * var(--u));letter-spacing:.4px;color:var(--secondary-text-color)}
.lb.dl{font-size:min(calc(11 * var(--u)),calc(11 * var(--g)));color:var(--secondary-text-color)}
.lb.dv{font-size:min(calc(11 * var(--u)),calc(11 * var(--g)));line-height:calc(15 * var(--u));padding:0 calc(3 * var(--u));border-radius:calc(3 * var(--u));
  background:var(--dev);color:var(--secondary-text-color)}
.lb.v{transform:translate(-50%,-50%) rotate(-90deg)}
.o{position:absolute;transform:translate(-50%,-50%);white-space:nowrap;pointer-events:auto}
.bd::after,.dot::after{content:"";position:absolute;inset:calc(-6 * var(--u)) 0}.dot::after{inset:-8px}
.bd.ni{padding:0 calc(12 * var(--u))}.bd.ni .info{padding-right:0}
.vv{display:flex;flex-direction:column;align-items:center;line-height:1.15;color:var(--primary-text-color)}
.vv.big{pointer-events:none}.vv.big .n{font-size:calc(11 * var(--u));line-height:1.3}.vv.big .s{font-size:calc(20 * var(--u));font-weight:400;line-height:1.2}
.vv.sm{flex-direction:row;gap:calc(4 * var(--u));cursor:pointer}.vv.sm .s{font-size:calc(11 * var(--u));line-height:1.3;color:var(--secondary-text-color)}
.vv.sm .n{line-height:1.3;font-size:calc(11 * var(--u))}.vv.sm.st{flex-direction:column;gap:0}
.vv.dk .s{color:#fff}.vv.dk .n{color:rgba(255,255,255,.72)}.vv.dk.sm .s{color:rgba(255,255,255,.9)}
.bd{display:inline-flex;align-items:center;gap:calc(6 * var(--u));height:calc(32 * var(--u));padding:0 calc(8 * var(--u));
  border-radius:calc(16 * var(--u));border:1px solid var(--ha-card-border-color,var(--divider-color,#e0e0e0));
  background:var(--ha-card-background,var(--card-background-color,#fff));box-sizing:border-box;cursor:pointer;
  font-family:var(--ha-font-family-body,Roboto,Noto,sans-serif);--mdc-icon-size:calc(16 * var(--u))}
.bd ha-icon{display:flex;color:var(--state-icon-color)}
.bd.warm ha-icon{color:var(--warm)}.bd.cold ha-icon{color:var(--cold)}
.info{display:flex;flex-direction:column;align-items:flex-start;padding-right:calc(4 * var(--u))}
.n{font-size:calc(10 * var(--u));font-weight:500;line-height:calc(10 * var(--u));letter-spacing:.1px;color:var(--secondary-text-color)}
.s{font-size:calc(12 * var(--u));font-weight:500;line-height:calc(16 * var(--u));letter-spacing:.1px;color:var(--primary-text-color)}
.bd.na .s{color:var(--disabled-text-color,#9e9e9e)}
.dot{display:flex;align-items:center;justify-content:center;border-radius:50%;box-sizing:border-box;cursor:pointer;
  width:calc(2 * 14 * var(--g));height:calc(2 * 14 * var(--g));--mdc-icon-size:calc(16 * var(--g));
  background:var(--card-background-color,#fff);border:calc(1.5 * var(--g)) solid var(--divider-color,#e0e0e0);
  color:var(--secondary-text-color)}
.dot ha-icon{display:flex}.dot.on ha-icon{color:var(--warm)}
.fin{fill:var(--devl)}
.hl{fill:rgba(255,255,255,.08)}
.eev{fill:var(--card-background-color,#fff);stroke:var(--secondary-text-color);stroke-opacity:.7;stroke-width:1.2;stroke-linejoin:round}
.ibtn{position:absolute;top:8px;right:4px;z-index:1;width:48px;height:48px;display:flex;align-items:center;justify-content:center;
  border-radius:50%;cursor:pointer;color:var(--secondary-text-color);--mdc-icon-size:24px}
.ibtn:focus{outline:none}.ibtn:focus-visible{outline:2px solid var(--primary-color,#03a9f4)}
.ibtn:hover{background:rgba(127,127,127,.12);color:var(--primary-text-color)}
.lay.hasinfo .hd{padding-right:56px;min-height:32px}
dialog.inf{border:none;padding:0;width:min(560px,calc(100vw - 32px));max-height:calc(100vh - 64px);box-sizing:border-box;
  border-radius:var(--ha-dialog-border-radius,24px);background:var(--ha-card-background,var(--card-background-color,#fff));
  color:var(--primary-text-color);font-family:var(--ha-font-family-body,Roboto,Noto,sans-serif);
  box-shadow:0 8px 32px rgba(0,0,0,.28)}
dialog.inf[open]{display:flex;flex-direction:column}
dialog.inf::backdrop{background:rgba(0,0,0,.32)}
@media (max-width:450px){dialog.inf{width:100vw;max-width:100vw;height:100%;max-height:100%;border-radius:0}}
.inf .ih{display:flex;align-items:center;gap:4px;padding:12px 16px 4px 8px}
.inf .ih .ibtn{position:static}
.inf h2{margin:0;font-size:var(--ha-font-size-xl,20px);line-height:28px;font-weight:var(--ha-font-weight-normal,400)}
.inf .ibd{overflow:auto;padding:4px 24px 24px;outline:none}
.inf p{margin:0;font-size:var(--ha-font-size-m,14px);line-height:20px;color:var(--secondary-text-color)}
.inf .ist{margin:16px 0 8px;padding:8px 12px;border-radius:12px;font-size:var(--ha-font-size-m,14px);line-height:20px;
  background:rgba(127,127,127,.10);color:var(--primary-text-color)}
.inf .step{display:grid;grid-template-columns:56px 1fr;column-gap:16px;padding:12px 0;border-top:1px solid var(--divider-color,#e0e0e0)}
.inf .step:first-of-type{border-top:none}
.inf .step svg{width:56px;height:56px;display:block}
.inf h3,.inf h4{margin:0 0 2px;font-size:var(--ha-font-size-l,16px);line-height:24px;font-weight:var(--ha-font-weight-medium,500)}
.inf .now{margin-top:6px;font-size:var(--ha-font-size-m,14px);line-height:20px;font-weight:500;color:var(--primary-text-color)}
.inf .now:empty{display:none}
.inf .tips{margin-top:8px;padding-top:12px;border-top:1px solid var(--divider-color,#e0e0e0)}
.inf .tips div+div{margin-top:12px}
.inf .leg{padding:12px 0;border-top:1px solid var(--divider-color,#e0e0e0)}
.inf .leg>div{display:flex;flex-wrap:wrap;gap:6px 20px}
.inf .leg span{display:inline-flex;align-items:center;gap:8px;font-size:var(--ha-font-size-m,14px);line-height:20px;color:var(--secondary-text-color)}
.inf .leg svg{width:56px;height:8px;overflow:visible}
.inf .leg .pipe{stroke-width:4}.inf .leg .pipe:not(.on){stroke:var(--secondary-text-color);stroke-opacity:.6}
.drop{fill:var(--cold)}
.itile{fill:var(--sky);fill-opacity:calc(var(--sky-a) * 1.6)}
.ifin{stroke:var(--devl);stroke-width:1.2}
.inf .pipe{stroke-width:3}
.bolt{fill:rgba(255,255,255,.85)}
.lay.wide :is(.ov,.hd){--u:clamp(0.9px,calc(100cqw / 790),1px);--g:calc(100cqw / 790)}.lay.wide .ptr{transform-origin:520px 244px}
.lay.narrow :is(.ov,.hd){--u:clamp(0.85px,calc(100cqw / 400),1px);--g:calc(100cqw / 400)}.lay.narrow .ptr{transform-origin:184px 432px}
.lay.kk :is(.ov,.hd){--u:clamp(0.9px,calc(100cqw / 790),1px);--g:calc(100cqw / 944)}.lay.kk .ptr{transform-origin:0px 0px}
.lay.kkn :is(.ov,.hd){--u:clamp(0.85px,calc(100cqw / 400),1px);--g:calc(100cqw / 400)}.lay.kkn .ptr{transform-origin:0px 0px}
